/**
 * The monochrome push badge — apps/staff/public/icons/badge-96.png.
 *
 * Android draws a Web Push notification's `badge` in the status bar as a
 * silhouette: it keeps the alpha channel and paints it one colour, so the
 * file is the brand mark in white on transparent, 96×96 (Chrome's
 * recommended size), with the same clear space a maskable icon gets. The
 * launcher icons (`icon-192.png` etc, docs/12 § Brand assets) predate this
 * script and are not regenerated by it.
 *
 * Rasterised with sharp, which the workspace already carries under Next
 * (nothing declares it), so it is resolved from there rather than added:
 *
 *   node apps/staff/scripts/gen-push-badge.mjs
 */
import { createRequire } from 'node:module';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO = join(HERE, '..', '..', '..');
const require = createRequire(import.meta.url);
const sharp = createRequire(require.resolve('next/package.json'))('sharp');

const SIZE = 96;
const PAD = 12; // ~12% clear space each side; the mark is tall, so it fills the height

const mark = readFileSync(join(REPO, 'brand', 'thc-mark.svg'), 'utf8');
// The source inherits CSS `color`; a standalone raster has none to inherit.
const white = mark.replace('fill="currentColor"', 'fill="#ffffff"');

const inner = await sharp(Buffer.from(white), { density: 600 })
  .resize(SIZE - 2 * PAD, SIZE - 2 * PAD, {
    fit: 'contain',
    background: { r: 0, g: 0, b: 0, alpha: 0 },
  })
  .png()
  .toBuffer();

const out = join(HERE, '..', 'public', 'icons', 'badge-96.png');
mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  await sharp({
    create: { width: SIZE, height: SIZE, channels: 4, background: { r: 0, g: 0, b: 0, alpha: 0 } },
  })
    .composite([{ input: inner, gravity: 'centre' }])
    .png()
    .toBuffer(),
);
console.warn(`wrote ${out}`);
